def get_endpoint_context(dependant: Any, route: Any) -> str:
    cache_key = (dependant, route)
    if cache_key in _endpoint_context_cache:
        return _endpoint_context_cache[cache_key]

    call = dependant.call
    if call is None:
        return ""

    try:
        file = inspect.getfile(call)
        line = inspect.getsourcelines(call)[1]
        name = call.__name__
    except Exception:
        return ""

    path = getattr(route, "path", "")
    methods = getattr(route, "methods", None)
    if methods is not None:
        method_str = " ".join(sorted(methods))
    else:
        method_str = "WS"

    context = f"  File \"{file}\", line {line}, in {name}\n    {method_str} {path}"
    _endpoint_context_cache[cache_key] = context
    return context


